-- Owner syllabus: Camp 1 (1–19), Camp 2 screen labels (20–45).
-- Camp 2 access ordinals remain 1–26; presentation offset +19 is in course-catalog.ts.
-- Adds public outline metadata only. No enrollments, material permissions or policies change.
begin;
lock table public.classroom_courses,public.classroom_levels,public.classroom_items,public.classroom_enrollments in share row exclusive mode;
do $camp$
begin
 if exists(select 1 from public.classroom_levels where course_id in ('camp-1','camp-2')) then
  if (select count(*) from public.classroom_levels where course_id in ('camp-1','camp-2'))=45
     and not exists(select 1 from jsonb_to_recordset($outline$[{"course_id": "camp-1", "number": 1, "title": "Differentiate"}, {"course_id": "camp-1", "number": 2, "title": "Integration"}, {"course_id": "camp-1", "number": 3, "title": "Vector"}, {"course_id": "camp-1", "number": 4, "title": "Log & Expo"}, {"course_id": "camp-1", "number": 5, "title": "Taylor's Expansion"}, {"course_id": "camp-1", "number": 6, "title": "Kinematics"}, {"course_id": "camp-1", "number": 7, "title": "Dynamics"}, {"course_id": "camp-1", "number": 8, "title": "Relative Motion"}, {"course_id": "camp-1", "number": 9, "title": "Non-inertia frame"}, {"course_id": "camp-1", "number": 10, "title": "Momentum"}, {"course_id": "camp-1", "number": 11, "title": "Energy"}, {"course_id": "camp-1", "number": 12, "title": "Electric Field"}, {"course_id": "camp-1", "number": 13, "title": "Gauss's Law"}, {"course_id": "camp-1", "number": 14, "title": "Electric Potential"}, {"course_id": "camp-1", "number": 15, "title": "Relation between E field & potential"}, {"course_id": "camp-1", "number": 16, "title": "Capacitor"}, {"course_id": "camp-1", "number": 17, "title": "Ohm's Law"}, {"course_id": "camp-1", "number": 18, "title": "Kirchhoff's Rules"}, {"course_id": "camp-1", "number": 19, "title": "Electric Power"}, {"course_id": "camp-2", "number": 1, "title": "Angular Momentum"}, {"course_id": "camp-2", "number": 2, "title": "Torque"}, {"course_id": "camp-2", "number": 3, "title": "Conservation Laws"}, {"course_id": "camp-2", "number": 4, "title": "Non-Fixed Axis Rotation"}, {"course_id": "camp-2", "number": 5, "title": "Zeroth Law"}, {"course_id": "camp-2", "number": 6, "title": "Heat Expansion"}, {"course_id": "camp-2", "number": 7, "title": "Heat Capacity"}, {"course_id": "camp-2", "number": 8, "title": "Heat Transfer"}, {"course_id": "camp-2", "number": 9, "title": "1st Law"}, {"course_id": "camp-2", "number": 10, "title": "2nd Law"}, {"course_id": "camp-2", "number": 11, "title": "Travelling Wave"}, {"course_id": "camp-2", "number": 12, "title": "Standing Wave"}, {"course_id": "camp-2", "number": 13, "title": "Interference and Diffraction"}, {"course_id": "camp-2", "number": 14, "title": "Beat"}, {"course_id": "camp-2", "number": 15, "title": "Doppler Effect"}, {"course_id": "camp-2", "number": 16, "title": "Biot-Savart Law"}, {"course_id": "camp-2", "number": 17, "title": "Ampere's Loop Law"}, {"course_id": "camp-2", "number": 18, "title": "Lorentz Force"}, {"course_id": "camp-2", "number": 19, "title": "Lenz Law"}, {"course_id": "camp-2", "number": 20, "title": "Faraday Law"}, {"course_id": "camp-2", "number": 21, "title": "Inductance"}, {"course_id": "camp-2", "number": 22, "title": "Maxwell's Equation"}, {"course_id": "camp-2", "number": 23, "title": "EM wave"}, {"course_id": "camp-2", "number": 24, "title": "AC circuit"}, {"course_id": "camp-2", "number": 25, "title": "Quantum"}, {"course_id": "camp-2", "number": 26, "title": "Relativity"}]$outline$::jsonb) as x(course_id text,number integer,title text)
       left join public.classroom_levels l using(course_id,number) where l.title is distinct from x.title)
  then return; end if;
  raise exception 'Existing camp syllabus differs; inspect before modifying';
 end if;
 if exists(select 1 from public.classroom_items where course_id in ('camp-1','camp-2')) or exists(select 1 from public.classroom_enrollments where course_id in ('camp-1','camp-2')) then
  raise exception 'Camp materials or enrollments appeared; review before initialization';
 end if;
 insert into public.classroom_levels(course_id,number,title,duration_minutes)
 select x.course_id,x.number,x.title,null from jsonb_to_recordset($outline$[{"course_id": "camp-1", "number": 1, "title": "Differentiate"}, {"course_id": "camp-1", "number": 2, "title": "Integration"}, {"course_id": "camp-1", "number": 3, "title": "Vector"}, {"course_id": "camp-1", "number": 4, "title": "Log & Expo"}, {"course_id": "camp-1", "number": 5, "title": "Taylor's Expansion"}, {"course_id": "camp-1", "number": 6, "title": "Kinematics"}, {"course_id": "camp-1", "number": 7, "title": "Dynamics"}, {"course_id": "camp-1", "number": 8, "title": "Relative Motion"}, {"course_id": "camp-1", "number": 9, "title": "Non-inertia frame"}, {"course_id": "camp-1", "number": 10, "title": "Momentum"}, {"course_id": "camp-1", "number": 11, "title": "Energy"}, {"course_id": "camp-1", "number": 12, "title": "Electric Field"}, {"course_id": "camp-1", "number": 13, "title": "Gauss's Law"}, {"course_id": "camp-1", "number": 14, "title": "Electric Potential"}, {"course_id": "camp-1", "number": 15, "title": "Relation between E field & potential"}, {"course_id": "camp-1", "number": 16, "title": "Capacitor"}, {"course_id": "camp-1", "number": 17, "title": "Ohm's Law"}, {"course_id": "camp-1", "number": 18, "title": "Kirchhoff's Rules"}, {"course_id": "camp-1", "number": 19, "title": "Electric Power"}, {"course_id": "camp-2", "number": 1, "title": "Angular Momentum"}, {"course_id": "camp-2", "number": 2, "title": "Torque"}, {"course_id": "camp-2", "number": 3, "title": "Conservation Laws"}, {"course_id": "camp-2", "number": 4, "title": "Non-Fixed Axis Rotation"}, {"course_id": "camp-2", "number": 5, "title": "Zeroth Law"}, {"course_id": "camp-2", "number": 6, "title": "Heat Expansion"}, {"course_id": "camp-2", "number": 7, "title": "Heat Capacity"}, {"course_id": "camp-2", "number": 8, "title": "Heat Transfer"}, {"course_id": "camp-2", "number": 9, "title": "1st Law"}, {"course_id": "camp-2", "number": 10, "title": "2nd Law"}, {"course_id": "camp-2", "number": 11, "title": "Travelling Wave"}, {"course_id": "camp-2", "number": 12, "title": "Standing Wave"}, {"course_id": "camp-2", "number": 13, "title": "Interference and Diffraction"}, {"course_id": "camp-2", "number": 14, "title": "Beat"}, {"course_id": "camp-2", "number": 15, "title": "Doppler Effect"}, {"course_id": "camp-2", "number": 16, "title": "Biot-Savart Law"}, {"course_id": "camp-2", "number": 17, "title": "Ampere's Loop Law"}, {"course_id": "camp-2", "number": 18, "title": "Lorentz Force"}, {"course_id": "camp-2", "number": 19, "title": "Lenz Law"}, {"course_id": "camp-2", "number": 20, "title": "Faraday Law"}, {"course_id": "camp-2", "number": 21, "title": "Inductance"}, {"course_id": "camp-2", "number": 22, "title": "Maxwell's Equation"}, {"course_id": "camp-2", "number": 23, "title": "EM wave"}, {"course_id": "camp-2", "number": 24, "title": "AC circuit"}, {"course_id": "camp-2", "number": 25, "title": "Quantum"}, {"course_id": "camp-2", "number": 26, "title": "Relativity"}]$outline$::jsonb) as x(course_id text,number integer,title text);
 update public.classroom_courses set level_count=case id when 'camp-1' then 19 when 'camp-2' then 26 end where id in ('camp-1','camp-2');
 if (select count(*) from public.classroom_levels where course_id='camp-1')<>19 or (select count(*) from public.classroom_levels where course_id='camp-2')<>26 then raise exception 'Camp outline count mismatch'; end if;
end $camp$;
commit;

